-- PostgreSQL 18 select_no_parens: after ORDER BY, LIMIT/OFFSET and the
-- row-locking clauses come in either order, but a locking clause cannot
-- follow a LIMIT that itself follows a locking clause.
CREATE TABLE l538 (a int, b int);
INSERT INTO l538 SELECT g % 5, g FROM generate_series(1, 40) g;
ANALYZE l538;
SELECT b FROM l538 ORDER BY b FOR UPDATE LIMIT 2;
SELECT b FROM l538 ORDER BY b FOR UPDATE OFFSET 1 LIMIT 2;
SELECT b FROM l538 ORDER BY b FOR SHARE OF l538 NOWAIT FETCH FIRST 2 ROWS ONLY;
SELECT b FROM l538 ORDER BY b LIMIT 2 FOR UPDATE;
SELECT b FROM l538 ORDER BY b LIMIT 2 FOR UPDATE LIMIT 1;
SELECT b FROM l538 ORDER BY b FOR UPDATE LIMIT 1 FOR SHARE;
SELECT b FROM l538 ORDER BY b FOR UPDATE LIMIT 1 OFFSET 1 OFFSET 2;
SELECT b FROM (SELECT * FROM l538 ORDER BY b FOR UPDATE LIMIT 1) s;
SELECT b FROM l538 WHERE b > 30 ORDER BY b FOR UPDATE SKIP LOCKED LIMIT 3;
EXPLAIN (COSTS OFF) SELECT * FROM l538 WHERE b < 10 FOR UPDATE LIMIT 3;
EXPLAIN (COSTS OFF) SELECT * FROM l538 ORDER BY b FOR NO KEY UPDATE OFFSET 2;
